import java.util.*;

class Solution {
    private static final int[][] DIRS = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};

    public int largestIsland(int[][] grid) {
        int n = grid.length;
        int[][] color = new int[n][n];
        Map<Integer, Integer> areaByColor = new HashMap<>();
        int nextColor = 2;
        int best = 0;
        boolean hasZero = false;

        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                if (grid[r][c] == 0) {
                    hasZero = true;
                } else if (color[r][c] == 0) {
                    int area = labelIsland(grid, color, r, c, nextColor);
                    areaByColor.put(nextColor, area);
                    best = Math.max(best, area);
                    nextColor++;
                }
            }
        }

        if (!hasZero) {
            return n * n;
        }

        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                if (grid[r][c] != 0) {
                    continue;
                }
                Set<Integer> seen = new HashSet<>();
                int merged = 1;
                for (int[] dir : DIRS) {
                    int nr = r + dir[0];
                    int nc = c + dir[1];
                    if (nr < 0 || nr >= n || nc < 0 || nc >= n || color[nr][nc] == 0) {
                        continue;
                    }
                    if (seen.add(color[nr][nc])) {
                        merged += areaByColor.get(color[nr][nc]);
                    }
                }
                best = Math.max(best, merged);
            }
        }

        return best;
    }

    private int labelIsland(int[][] grid, int[][] color, int sr, int sc, int value) {
        int n = grid.length;
        ArrayDeque<int[]> stack = new ArrayDeque<>();
        stack.push(new int[]{sr, sc});
        color[sr][sc] = value;
        int area = 0;

        while (!stack.isEmpty()) {
            int[] cell = stack.pop();
            area++;
            for (int[] dir : DIRS) {
                int nr = cell[0] + dir[0];
                int nc = cell[1] + dir[1];
                if (nr >= 0 && nr < n && nc >= 0 && nc < n
                        && grid[nr][nc] == 1 && color[nr][nc] == 0) {
                    color[nr][nc] = value;
                    stack.push(new int[]{nr, nc});
                }
            }
        }
        return area;
    }
}

