    public int largestIsland(int[][] grid) {
        int n = grid.length;
        parent = new int[n * n];
        size = new int[n * n];
        for (int i = 0; i < n * n; i++) {
            parent[i] = i;
        }

        boolean hasZero = false;
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                int id = r * n + c;
                if (grid[r][c] == 0) {
                    hasZero = true;
                } else {
                    size[id] = 1;
                }
            }
        }

        int[][] dirs = {{1, 0}, {0, 1}};
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                if (grid[r][c] == 0) {
                    continue;
                }
                int id = r * n + c;
                for (int[] dir : dirs) {
                    int nr = r + dir[0];
                    int nc = c + dir[1];
                    if (nr < n && nc < n && grid[nr][nc] == 1) {
                        union(id, nr * n + nc);
                    }
                }
            }
        }

        if (!hasZero) {
            return n * n;
        }

        int best = 1;
        for (int id = 0; id < n * n; id++) {
            if (parent[id] == id) {
                best = Math.max(best, size[id]);
            }
        }

        int[][] allDirs = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                if (grid[r][c] != 0) {
                    continue;
                }
                Set<Integer> seenRoots = new HashSet<>();
                int merged = 1;
                for (int[] dir : allDirs) {
                    int nr = r + dir[0];
                    int nc = c + dir[1];
                    if (nr >= 0 && nr < n && nc >= 0 && nc < n && grid[nr][nc] == 1) {
                        int root = find(nr * n + nc);
                        if (seenRoots.add(root)) {
                            merged += size[root];
                        }
                    }
                }
                best = Math.max(best, merged);
            }
        }
        return best;
    }

    private int find(int x) {
        while (parent[x] != x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    }

    private void union(int a, int b) {
        int rootA = find(a);
        int rootB = find(b);
        if (rootA == rootB) {
            return;
        }
        if (size[rootA] < size[rootB]) {
            int tmp = rootA;
            rootA = rootB;
            rootB = tmp;
        }
        parent[rootB] = rootA;
        size[rootA] += size[rootB];
    }
}

