    public int largestIsland(int[][] grid) {
        int n = grid.length;
        Map<Integer, Integer> sizeByColor = new HashMap<>();
        int color = 2;
        int best = 0;
        boolean hasZero = false;

        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                if (grid[r][c] == 0) {
                    hasZero = true;
                } else if (grid[r][c] == 1) {
                    int size = colorIsland(grid, r, c, color);
                    sizeByColor.put(color, size);
                    best = Math.max(best, size);
                    color++;
                }
            }
        }

        if (!hasZero) {
            return n * n;
        }

        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                if (grid[r][c] != 0) {
                    continue;
                }
                Set<Integer> seen = new HashSet<>();
                int merged = 1;
                for (int[] dir : DIRS) {
                    int nr = r + dir[0];
                    int nc = c + dir[1];
                    if (nr < 0 || nr >= n || nc < 0 || nc >= n || grid[nr][nc] <= 1) {
                        continue;
                    }
                    if (seen.add(grid[nr][nc])) {
                        merged += sizeByColor.get(grid[nr][nc]);
                    }
                }
                best = Math.max(best, merged);
            }
        }
        return best;
    }

    private int colorIsland(int[][] grid, int sr, int sc, int color) {
        int n = grid.length;
        ArrayDeque<int[]> queue = new ArrayDeque<>();
        queue.offer(new int[]{sr, sc});
        grid[sr][sc] = color;
        int size = 0;

        while (!queue.isEmpty()) {
            int[] cur = queue.poll();
            size++;
            for (int[] dir : DIRS) {
                int nr = cur[0] + dir[0];
                int nc = cur[1] + dir[1];
                if (nr >= 0 && nr < n && nc >= 0 && nc < n && grid[nr][nc] == 1) {
                    grid[nr][nc] = color;
                    queue.offer(new int[]{nr, nc});
                }
            }
        }
        return size;
    }
}

