class Solution {
    private static final int[][] DIRS = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};

    public int largestIsland(int[][] grid) {
        int n = grid.length;
        int[][] color = new int[n][n];
        Map<Integer, Integer> areaByColor = new HashMap<>();
        int nextColor = 2;
        int bestExisting = 0;
        boolean hasZero = false;

        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                if (grid[r][c] == 0) {
                    hasZero = true;
                } else if (color[r][c] == 0) {
                    int area = paint(grid, color, r, c, nextColor);
                    areaByColor.put(nextColor, area);
                    bestExisting = Math.max(bestExisting, area);
                    nextColor++;
                }
            }
        }

        if (!hasZero) {
            return n * n;
        }

        int[] candidate = new int[n * n];
        Map<Integer, Set<Integer>> colorsByZero = new HashMap<>();
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                int islandColor = color[r][c];
                if (islandColor == 0) {
                    continue;
                }
                for (int[] dir : DIRS) {
                    int nr = r + dir[0];
                    int nc = c + dir[1];
                    if (nr < 0 || nr >= n || nc < 0 || nc >= n || grid[nr][nc] != 0) {
                        continue;
                    }
                    int zeroIndex = nr * n + nc;
                    Set<Integer> colors = colorsByZero.computeIfAbsent(zeroIndex, ignored -> new HashSet<>());
                    if (colors.add(islandColor)) {
                        if (candidate[zeroIndex] == 0) {
                            candidate[zeroIndex] = 1;
                        }
                        candidate[zeroIndex] += areaByColor.get(islandColor);
                    }
                }
            }
        }

        int best = Math.max(bestExisting, 1);
        for (int area : candidate) {
            best = Math.max(best, area);
        }
        return best;
    }

    private int paint(int[][] grid, int[][] color, int sr, int sc, int islandColor) {
        int n = grid.length;
        ArrayDeque<int[]> stack = new ArrayDeque<>();
        stack.push(new int[]{sr, sc});
        color[sr][sc] = islandColor;
        int area = 0;
        while (!stack.isEmpty()) {
            int[] cell = stack.pop();
            area++;
            for (int[] dir : DIRS) {
                int nr = cell[0] + dir[0];
                int nc = cell[1] + dir[1];
                if (nr >= 0 && nr < n && nc >= 0 && nc < n
                        && grid[nr][nc] == 1 && color[nr][nc] == 0) {
                    color[nr][nc] = islandColor;
                    stack.push(new int[]{nr, nc});
                }
            }
        }
        return area;
    }
}

