class Solution {
    private int[] parent;
    private int[] size;

    public int largestIsland(int[][] grid) {
        int n = grid.length;
        int[][] runId = new int[n][n];
        for (int[] row : runId) {
            Arrays.fill(row, -1);
        }
        parent = new int[n * n];
        size = new int[n * n];

        int runs = 0;
        boolean hasZero = false;
        for (int r = 0; r < n; r++) {
            int c = 0;
            while (c < n) {
                if (grid[r][c] == 0) {
                    hasZero = true;
                    c++;
                    continue;
                }
                int start = c;
                while (c < n && grid[r][c] == 1) {
                    c++;
                }
                parent[runs] = runs;
                size[runs] = c - start;
                for (int x = start; x < c; x++) {
                    runId[r][x] = runs;
                }
                runs++;
            }
        }

        if (runs == 0) {
            return 1;
        }

        for (int r = 1; r < n; r++) {
            for (int c = 0; c < n; c++) {
                int current = runId[r][c];
                int above = runId[r - 1][c];
                if (current != -1 && above != -1) {
                    union(current, above);
                }
            }
        }

        int best = 0;
        for (int id = 0; id < runs; id++) {
            if (find(id) == id) {
                best = Math.max(best, size[id]);
            }
        }
        if (!hasZero) {
            return n * n;
        }

        int[][] dirs = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                if (grid[r][c] != 0) {
                    continue;
                }
                int merged = 1;
                int[] seenRoots = new int[4];
                int seenCount = 0;
                for (int[] dir : dirs) {
                    int nr = r + dir[0];
                    int nc = c + dir[1];
                    if (nr < 0 || nr >= n || nc < 0 || nc >= n || runId[nr][nc] == -1) {
                        continue;
                    }
                    int root = find(runId[nr][nc]);
                    boolean duplicate = false;
                    for (int i = 0; i < seenCount; i++) {
                        if (seenRoots[i] == root) {
                            duplicate = true;
                            break;
                        }
                    }
                    if (!duplicate) {
                        seenRoots[seenCount++] = root;
                        merged += size[root];
                    }
                }
                best = Math.max(best, merged);
            }
        }
        return best;
    }

    private int find(int x) {
        while (parent[x] != x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    }

    private void union(int a, int b) {
        int rootA = find(a);
        int rootB = find(b);
        if (rootA == rootB) {
            return;
        }
        if (size[rootA] < size[rootB]) {
            int tmp = rootA;
            rootA = rootB;
            rootB = tmp;
        }
        parent[rootB] = rootA;
        size[rootA] += size[rootB];
    }
}
